    // \u3053\u3053\u306B Bluetooth \u901A\u4FE1\u30ED\u30B8\u30C3\u30AF\u3092\u8A18\u8FF0\u3067\u304D\u307E\u3059\n    while(1)  {\n        temp=blueToothSerial.read();\n        switch(temp)  {\n            case \'O\':{while(temp!=\'N\')  {temp=blueToothSerial.read();}  digitalWrite(5,HIGH);break;}\n            case \'S\':{while(temp!=\'H\')  {temp=blueToothSerial.read();}  digitalWrite(5,LOW);break;}\n            default:break;\n        }\n    }\n}\n\n\nvoid setupBlueToothConnection()\n{\n    blueToothSerial.begin(38400); // BluetoothBee \u306E\u30C7\u30D5\u30A9\u30EB\u30C8\u30DC\u30FC\u30EC\u30FC\u30C8 38400 \u306B\u8A2D\u5B9A\n    delay(1000);\n    sendBlueToothCommand("\\r\\n+STWMOD=0\\r\\n");\n    sendBlueToothCommand("\\r\\n+STNA=SeeedBluetooth-st\\r\\n");\n    sendBlueToothCommand("\\r\\n+STAUTO=0\\r\\n");\n    sendBlueToothCommand("\\r\\n+STOAUT=1\\r\\n");\n    sendBlueToothCommand("\\r\\n +STPIN=0000\\r\\n");\n    delay(2000); // \u3053\u306E\u9045\u5EF6\u306F\u5FC5\u8981\u3067\u3059\u3002\n    sendBlueToothCommand("\\r\\n+INQ=1\\r\\n");\n    delay(2000); // \u3053\u306E\u9045\u5EF6\u306F\u5FC5\u8981\u3067\u3059\u3002\n}\n\n// \u5FDC\u7B54 "OK" \u304C\u53D7\u4FE1\u3055\u308C\u305F\u304B\u78BA\u8A8D\nvoid CheckOK()\n{\n    char a,b;\n    while(1)\n    {\n        if(blueToothSerial.available())\n        {\n            a = blueToothSerial.read();\n\n            if(\'O\' == a)\n            {\n                // \u6B21\u306E\u6587\u5B57 K \u3092\u5F85\u6A5F\u3057\u307E\u3059\u3002\u5834\u5408\u306B\u3088\u3063\u3066\u306F available() \u304C\u5FC5\u8981\u3067\u3059\u3002K \u304C\u3059\u3050\u306B\u5229\u7528\u53EF\u80FD\u3067\u306F\u306A\u3044\u5834\u5408\u304C\u3042\u308A\u307E\u3059\u3002\n                while(blueToothSerial.available())\n                {\n                    b = blueToothSerial.read();\n                    break;\n                }\n                if(\'K\' == b)\n                {\n                    break;\n                }\n            }\n        }\n    }\n\n    while( (a = blueToothSerial.read()) != -1)\n    {\n        // \u4ED6\u306E\u5FDC\u7B54\u6587\u5B57\u304C\u3059\u3079\u3066\u53D7\u4FE1\u3055\u308C\u308B\u307E\u3067\u5F85\u6A5F\n    }\n}\n\nvoid sendBlueToothCommand(char command[])\n{\n    blueToothSerial.print(command);\n    CheckOK();\n}\n'})}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"\u30B9\u30C6\u30C3\u30D7 3"}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:["XBee \u30AD\u30E3\u30EA\u30A2\u3092 USB \u30B1\u30FC\u30D6\u30EB\u3067\u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u306B\u63A5\u7D9A\u3057\u3001Bluetooth Bee-Standalone \u4E0A\u306E ",(0,i.jsx)(n.strong,{children:"ATMEGA168"})," \u306B\u30D7\u30ED\u30B0\u30E9\u30E0\u3092\u30A2\u30C3\u30D7\u30ED\u30FC\u30C9\u3057\u307E\u3059\u3002"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"\u30B9\u30C6\u30C3\u30D7 4"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"XBee \u30AD\u30E3\u30EA\u30A2\u304B\u3089 USB \u30B1\u30FC\u30D6\u30EB\u3092\u53D6\u308A\u5916\u3057\u30013.7V \u30D0\u30C3\u30C6\u30EA\u30FC\u3092\u4EE5\u4E0B\u306E\u3088\u3046\u306B XBee \u30AD\u30E3\u30EA\u30A2\u306B\u63A5\u7D9A\u3057\u307E\u3059\u3002"}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://files.seeedstudio.com/wiki/Bluetooth_Bee_Standalone/img/Bluetooth_Bee-Standalone2.jpg",alt:""})}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"\u30B9\u30C6\u30C3\u30D7 5"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{src:"https://files.seeedstudio.com/wiki/Bluetooth_Bee_Standalone/img/Bluetooth_Bee-Standalone1.jpg",alt:""})}),"\n",(0,i.jsx)(n.h2,{id:"\u8FFD\u52A0\u306E\u30A2\u30A4\u30C7\u30A2",children:"\u8FFD\u52A0\u306E\u30A2\u30A4\u30C7\u30A2"}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:(0,i.jsx)(n.a,{href:"http://dejwoot.blogspot.hk/2012/07/howto-test-your-bluetooth-bee-standalone.html",children:"Bluetooth Bee - Standalone \u306E\u30C6\u30B9\u30C8\u65B9\u6CD5"})}),"\n"]}),"\n",(